  /**
   * Retorna o XML do bloco pre-textual (Indice de Figuras, Tabelas e Sumario)
   * ajustando legendas de figuras de acordo com a carga horaria se necessario.
   */
  function getReportPretextualXml(is16Hours) {
    var xml = PRETEXTUAL_RAW_XML;
    if (is16Hours) {
      xml = xml.replace('Figura 12. Apresenta\u00e7\u00e3o do Software SETE.', 'Figura 12. Apresenta\u00e7\u00e3o do primeiro dia.');
      xml = xml.replace('Figura 13. Final da capacita\u00e7\u00e3o.', 'Figura 13. Final da capacita\u00e7\u00e3o do segundo dia.');
    } else {
      xml = xml.replace('Figura 12. Apresenta\u00e7\u00e3o do primeiro dia.', 'Figura 12. Apresenta\u00e7\u00e3o do Software SETE.');
      xml = xml.replace('Figura 13. Final da capacita\u00e7\u00e3o do segundo dia.', 'Figura 13. Final da capacita\u00e7\u00e3o.');
    }
    return xml;
  }

  window.getReportPretextualXml = getReportPretextualXml;
